CREATE TABLE IF NOT EXISTS usuarios (id INTEGER PRIMARY KEY, apelido TEXT UNIQUE NOT NULL COLLATE NOCASE, pin_hash TEXT NOT NULL, salt TEXT NOT NULL, admin INTEGER NOT NULL DEFAULT 0, falhas INTEGER NOT NULL DEFAULT 0, bloqueado_ate INTEGER NOT NULL DEFAULT 0, criado INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessoes (token TEXT PRIMARY KEY, usuario_id INTEGER NOT NULL, expira INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessoes_usuario ON sessoes(usuario_id);
CREATE TABLE IF NOT EXISTS saves (usuario_id INTEGER NOT NULL, slot INTEGER NOT NULL, nome TEXT NOT NULL, resumo TEXT, atualizado INTEGER NOT NULL, dados TEXT NOT NULL, PRIMARY KEY (usuario_id, slot));
CREATE TABLE IF NOT EXISTS mural (id INTEGER PRIMARY KEY, quando INTEGER NOT NULL, autor TEXT NOT NULL, acao TEXT NOT NULL, detalhe TEXT);
